def refs():
    return [{**s, "subject": "science", "locator": "光照、二氧化碳、溫度與水分的限制因子、速率曲線、平台及控制變因", "observedPattern": "公開公立學校生物資料常用水草產氣、遮光／二氧化碳處理與曲線判讀，要求學生從對照和資料設計推論；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, answer, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-bc-iv-4-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開生物科資料僅供光合作用探究、限制因子與資料判讀的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公開公立學校生物科資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "若要研究光照強度對水草光合作用速率的影響，哪個作法最合理？", {"A": "只改變光源距離，固定水草量、溫度、二氧化碳與測量時間", "B": "改變光源距離時也同時更換水草種類", "C": "每組使用不同測量時間", "D": "一組有光、另一組連溫度也改變"}, "A", "研究單一因素時，光照強度是自變因，其餘重要條件應固定，選 A。", "先指出自變因，再逐項檢查材料、環境和觀察時間是否被控制。", ["把光照強度設定為唯一自變因。", "水草量與種類會影響產氧量，需固定。", "溫度、二氧化碳和水分也要一致。", "各組使用相同測量時間比較產氣速率。", "所以選 A。"], "easy"),
    make(2, "某水草在光照逐漸增強時，產氧速率先增加後維持平台。平台最可能表示？", {"A": "光照不再是主要限制，其他因素成為瓶頸", "B": "水草停止所有代謝", "C": "氧氣不再能被測量", "D": "光照越強一定使葉綠素消失"}, "A", "曲線平台表示在該條件範圍內再增加光照，速率提升受其他限制因子阻礙，不代表所有代謝停止，選 A。", "看曲線斜率和平台位置，再尋找沒有同步增加的限制條件。", ["確認低光區速率隨光照增加。", "平台表示增加光照沒有帶來相同比例的速率增加。", "二氧化碳、溫度或酵素系統可能成為限制。", "不能把平台解讀成水草死亡或完全停止代謝。", "所以選 A。"], "medium"),
    make(3, "若要比較兩種二氧化碳濃度，哪項應作為主要應變因？", {"A": "固定時間內產生的氧氣體積或產氧速率", "B": "兩組燈具的品牌", "C": "實驗者穿著的顏色", "D": "培養瓶的編號"}, "A", "應變因要反映光合作用結果，固定時間的產氧量或速率可量化比較；其他選項不是反應結果，選 A。", "問『哪個量會因自變因改變而回應』，避免把管理欄位當成科學測量。", ["二氧化碳濃度是自變因。", "需要選擇可量化的光合作用結果。", "產氧量或單位時間產氧速率可作應變因。", "測量方法與時間需一致。", "所以選 A。"], "easy"),
    make(4, "某研究同時提高光照和二氧化碳濃度，觀察到產氧量增加。此結果的主要限制是？", {"A": "不能確定增加是由光照、二氧化碳，或兩者交互作用造成", "B": "產氧量增加就能證明只有光照有效", "C": "同時改變兩項會讓所有資料失效", "D": "二氧化碳不可能影響光合作用"}, "A", "兩個自變因同時變動，無法將各自效果分離；需要額外組別或一次只改變一項，選 A。", "看到多項條件同時改變，就先指出歸因不唯一，再提出可修正的設計。", ["列出光照與二氧化碳都是可能影響因素。", "兩者同時增加造成混淆變因。", "結果只能說總條件改變後產氧量增加。", "需設計單因素組合或分開實驗。", "因此選 A。"], "medium"),
    make(5, "溫度對光合作用速率的曲線先升後降，超過適宜溫度後速率下降的合理解釋是？", {"A": "相關酵素或細胞結構受高溫影響，活性下降", "B": "高溫使二氧化碳自動變成氧氣", "C": "溫度越高水草就不需要光", "D": "曲線下降必定表示測量者沒有使用葉綠體"}, "A", "光合作用包含酵素參與的反應；過高溫度可能使酵素活性下降或細胞受損，選 A。", "依曲線的適宜區間判斷，不把『溫度提高』簡化成永遠促進。", ["低溫區升溫可提高反應速率。", "到達適宜溫度後，系統效率達到較佳狀態。", "過高溫度可能破壞酵素構形或膜系統。", "因此產氧速率轉而下降。", "所以選 A。"], "hard"),
    make(6, "同一批水草做三次產氧測量，結果分別為 18、21、19 顆氣泡。最適合的處理方式是？", {"A": "計算平均並報告變異，不能只挑最大值", "B": "只保留 21 顆以宣稱效果最好", "C": "刪掉所有不符合預期的數據", "D": "把三次數據當成三種不同光照"}, "A", "重複測量可估計平均趨勢與誤差；只挑最大值會造成選擇偏差，選 A。", "先確認重複測量的目的，再以全部有效資料呈現中心趨勢和不確定性。", ["三次測量使用相同條件。", "數據有自然波動，不應只看一次。", "平均值可描述整體趨勢。", "同時報告範圍或變異可呈現不確定性。", "所以選 A。"], "medium"),
    make(7, "在弱光下增加二氧化碳後產氧速率幾乎不變，最合理的推論是？", {"A": "弱光可能是主要限制因子，增加二氧化碳無法解除它", "B": "二氧化碳永遠不會影響光合作用", "C": "水草必定沒有葉綠體", "D": "產氧速率不需要任何環境因素"}, "A", "當光能供應不足時，二氧化碳不是當下最主要瓶頸；增加它不一定提高速率，選 A。", "先找出未被補足的限制因子，而不是把一次無效處理推成普遍定律。", ["條件先固定在弱光。", "增加二氧化碳後速率仍近似不變。", "表示光能供應可能限制反應。", "若提高光照後才有反應，能進一步驗證推論。", "因此選 A。"], "hard"),
    make(8, "以氣泡數估計水草光合作用速率時，哪項是重要的測量限制？", {"A": "氣泡大小可能不同，氣泡數未必等於相同體積的氧氣", "B": "氣泡數永遠能直接代表葡萄糖質量", "C": "只要數氣泡就不需固定時間", "D": "氣泡一定全部來自光合作用而無需對照"}, "A", "氣泡大小與脫落方式會影響數量；氣泡數是方便的間接指標，不等於固定氣體體積，選 A。", "檢查指標是否直接、是否需要校正，以及有哪些替代測量方法。", ["氣泡數反映產氣事件，不必然反映每次體積。", "不同大小氣泡會造成估計誤差。", "應固定時間並可改用集氣量測量。", "適當對照也能排除非光合作用氣泡。", "所以選 A。"], "medium"),
    make(9, "若比較不同光照距離，卻使用大小差異很大的水草枝條，最可能造成什麼問題？", {"A": "水草量成為混淆變因，產氧差異未必來自光照", "B": "水草大小差異能保證結論更準確", "C": "光照距離會自動變成控制變因", "D": "只要有重複測量就不需統一材料"}, "A", "水草枝條量與葉面積會影響光合作用量；若不一致，就無法把差異單獨歸因於光照距離，選 A。", "逐項檢查除了自變因外，是否還有會直接改變產氧量的材料差異。", ["光照距離是預定自變因。", "枝條大小會改變葉面積與葉綠體總量。", "材料差異會影響產氧量。", "應使用相近大小或依葉面積校正。", "所以是不受控的混淆變因，選 A。"], "medium"),
    make(10, "某曲線在測試範圍內呈現平台，哪個結論最符合科學證據？", {"A": "只能說在本材料與範圍內繼續提高該因素未明顯增加速率", "B": "可以斷言任何植物在所有條件下都不會再增加", "C": "平台表示光合作用完全停止", "D": "平台必定是數據造假"}, "A", "平台結論受材料、範圍與控制條件限制；它不等於所有植物或所有範圍都無法增加，選 A。", "把結論綁定到實驗材料和範圍，避免從有限曲線過度外推。", ["確認曲線平台出現在特定測試範圍。", "描述該範圍內的實際觀察。", "指出其他限制因子可能成為瓶頸。", "不把局部結果推廣到所有植物與無限範圍。", "所以選 A。"], "hard"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    old = {o["id"]: o["text"] for o in q["options"]}
    old["A"], old[target] = old[target], old["A"]
    q["options"] = [{"id": k, "text": old[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A", f"選 {target}")
    q["solutionStrategy"] = q["solutionStrategy"].replace("選 A", f"選 {target}")
    q["solutionSteps"] = [s.replace("選 A", f"選 {target}").replace("所以選 A", f"所以選 {target}") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
